style.css:
/* Hello Kitty Dreamland - Roblox */

:root {
  /* swap these colours if you want */
  --my-pink: #f2bfd5;
  --my-light-pink: #ffe4ef;
  --my-hot-pink: #ec75aa;
  --my-black: #171016;
  --my-white: #fffafd;
}

/* pink page background */
body {
  background-color: var(--my-pink) !important;
  color: var(--my-black) !important;
  font-family: "Trebuchet MS", sans-serif !important;
}

/* cute pink links */
a {
  color: #d94d91 !important;
}

/* pink buttons */
button {
  background: var(--my-hot-pink) !important;
  color: white !important;
  border: 2px solid var(--my-black) !important;
  border-radius: 18px !important;
  font-weight: bold !important;
}

/* soft input boxes */
input, textarea {
  background: var(--my-white) !important;
  border: 2px solid var(--my-hot-pink) !important;
  border-radius: 12px !important;
  color: var(--my-black) !important;
}

/* rounded pictures */
img {
  border-radius: 14px !important;
}
